arguments.command:
curl -s -X POST https://slack.com/api/conversations.list -H "Authorization: Bearer <TOKEN>" --data-urlencode "types=public_channel" --data-urlencode "limit=1000" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERROR:', d.get('error'), d.get('msg'))
else:
    for c in d['channels']:
        if 'launch' in c['name'].lower():
            print(c['id'], c['name'], c.get('is_archived'), c.get('is_general'))
"

